components.css:
.ds-render { box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center; min-height: 44px; padding: 0 12px; border-radius: 6px; font: 700 15px/1.2 var(--ui, Barlow, system-ui, sans-serif); white-space: nowrap; border: 1px solid #b18c1e; background: var(--yellow, #f9d65c); color: var(--navy, #182c4b); }
.ds-render:enabled { cursor: pointer; }
.ds-render:hover:enabled:not([aria-disabled="true"]) { background: var(--yellow-hover, #ffe591); }
.ds-render:disabled, .ds-render[aria-disabled="true"] { background: #e7eaf0; color: #4d627f; border-color: #95a8bd; cursor: default; }
.ds-render:focus-visible { outline: 3px solid var(--focus, #235c9e); outline-offset: 3px; }
@media (max-width: 760px) { .ds-render { padding-inline: 9px; } }

.ds-download { box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center; min-height: 44px; padding: 0 12px; border-radius: 6px; font: 700 15px/1.2 var(--ui, Barlow, system-ui, sans-serif); white-space: nowrap; border: 1px solid #91a8c3; background: var(--surface, #fbfcfe); color: var(--navy, #182c4b); text-decoration: none; }
.ds-download:hover { background: #edf4fc; color: var(--navy, #182c4b); }
.ds-download:focus-visible { outline: 3px solid var(--focus, #235c9e); outline-offset: 3px; }
@media (max-width: 760px) { .ds-download { padding-inline: 9px; } }

.ds-copy { box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center; min-height: 44px; padding: 0 12px; border-radius: 6px; font: 700 15px/1.2 var(--ui, Barlow, system-ui, sans-serif); white-space: nowrap; border: 1px solid #91a8c3; background: var(--surface, #fbfcfe); color: var(--navy, #182c4b); font-weight: 600; }
.ds-copy:enabled { cursor: pointer; }
.ds-copy:hover:enabled { background: #eaf1f9; }
.ds-copy:disabled { color: var(--blue, #3a5b8a); }
.ds-copy:focus-visible { outline: 3px solid var(--focus, #235c9e); outline-offset: 3px; }

.ds-prompt { display: grid; gap: 7px; font: 400 17px/1.45 var(--ui, Barlow, system-ui, sans-serif); color: var(--navy, #182c4b); }
.ds-prompt-label { font-weight: 600; }
.ds-prompt-field { box-sizing: border-box; display: block; width: 100%; resize: vertical; min-height: 95px; padding: 10px 12px; border: 1px solid #91a8c3; border-radius: 8px; background: var(--surface, #fbfcfe); color: var(--navy, #182c4b); font: inherit; }
.ds-prompt-field:focus-visible { outline: 3px solid var(--focus, #235c9e); outline-offset: 3px; }
.ds-prompt-field::selection { background: var(--yellow, #f9d65c); color: var(--navy, #182c4b); }
@media (max-width: 390px) { .ds-prompt-field { min-height: 148px; } }

.ds-header { background: var(--navy, #182c4b); color: var(--surface, #fbfcfe); font: 400 17px/1.45 var(--ui, Barlow, system-ui, sans-serif); }
.ds-header-inner { width: min(1440px, calc(100% - 2 * var(--page-padding, clamp(16px, 3.6vw, 60px)))); margin-inline: auto; display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 72px; }
.ds-header a { display: inline-flex; align-items: center; min-height: 44px; color: inherit; text-decoration: none; }
.ds-header a:hover { text-decoration: underline; text-underline-offset: 4px; }
.ds-header a:focus-visible { outline: 3px solid var(--yellow, #f9d65c); outline-offset: 3px; }
.ds-wordmark { font: 700 29px/1 var(--display, "Barlow Semi Condensed", Arial, sans-serif); letter-spacing: -.02em; }
.ds-links { display: flex; gap: clamp(14px, 2.3vw, 32px); font-weight: 600; }
@media (max-width: 760px) {
  .ds-header-inner { min-height: 57px; }
  .ds-wordmark { font-size: 25px; }
  .ds-links { gap: clamp(10px, 3vw, 18px); font-size: 16px; }
}
@media (max-width: 360px) {
  .ds-header-inner, .ds-links { gap: 8px; }
  .ds-links { font-size: 15px; }
}

.ds-source-pane { min-width: 0; overflow: hidden; border: 1px solid var(--border, #becddd); border-radius: 13px; background: var(--surface, #fbfcfe); color: var(--navy, #182c4b); }
.ds-pane-bar { box-sizing: border-box; display: flex; align-items: center; justify-content: space-between; gap: 8px; min-height: 60px; padding: 7px 18px; border-bottom: 1px solid var(--border, #becddd); background: var(--sign, #dbe6f2); }
.ds-pane-title { flex: none; margin: 0; font: 700 20px/1.2 var(--ui, Barlow, system-ui, sans-serif); }
.ds-file-actions { display: flex; gap: 12px; align-items: center; min-width: 0; }
.ds-filename { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--blue, #3a5b8a); font: 500 13px/1.25 var(--mono, "IBM Plex Mono", ui-monospace, monospace); }
.ds-render { box-sizing: border-box; display: inline-flex; align-items: center; justify-content: center; min-height: 44px; padding: 0 12px; border-radius: 6px; font: 700 15px/1.2 var(--ui, Barlow, system-ui, sans-serif); white-space: nowrap; border: 1px solid #b18c1e; background: var(--yellow, #f9d65c); color: var(--navy, #182c4b); flex: none; }
.ds-render:enabled { cursor: pointer; }
.ds-render:hover:enabled:not([aria-disabled="true"]) { background: var(--yellow-hover, #ffe591); }
.ds-render:disabled, .ds-render[aria-disabled="true"] { background: #e7eaf0; color: #4d627f; border-color: #95a8bd; cursor: default; }
.ds-render:focus-visible { outline: 3px solid var(--focus, #235c9e); outline-offset: 3px; }
.ds-editor { display: grid; grid-template-columns: 52px minmax(0, 1fr); }
.ds-editor:focus-within { outline: 2px solid #779ac3; outline-offset: -2px; }
.ds-gutter, .ds-source { box-sizing: border-box; margin: 0; padding: var(--editor-inset, 20px) 14px; font: 400 var(--editor-size, 14px)/var(--editor-line, 27px) var(--mono, "IBM Plex Mono", ui-monospace, monospace); tab-size: 2; white-space: pre; }
.ds-gutter { overflow: hidden; user-select: none; text-align: right; color: var(--blue, #3a5b8a); background: var(--code-field, #edf3f9); border-right: 1px solid var(--rule, #d9e3ef); font-variant-numeric: tabular-nums; }
.ds-source { overflow: auto; scrollbar-color: #91a8c3 var(--surface, #fbfcfe); }
.ds-source:focus-visible { outline: 3px solid var(--focus, #235c9e); outline-offset: -3px; }
.ds-source::selection, .ds-source span::selection { background: rgb(249 214 92 / 55%); }
.ds-directive { color: #234f89; font-weight: 500; }
.ds-string { color: #236256; }
@media (max-width: 1160px) {
  .ds-pane-bar { padding-inline: 12px; }
  .ds-editor { grid-template-columns: 43px minmax(0, 1fr); }
}
@media (max-width: 760px) {
  .ds-pane-bar { min-height: 55px; }
  .ds-pane-title { font-size: 18px; }
  .ds-file-actions { gap: 7px; }
  .ds-filename { font-size: 11px; }
  .ds-render { padding-inline: 9px; }
  .ds-editor { grid-template-columns: 37px minmax(0, 1fr); }
  .ds-gutter, .ds-source { padding: var(--editor-inset, 12px) 9px; font-size: var(--editor-size, 16px); line-height: var(--editor-line, 26px); }
}

.ds-examples { width: min(100%, 840px); border-collapse: collapse; background: var(--surface, #fbfcfe); color: var(--navy, #182c4b); text-align: left; font: 400 17px/1.45 var(--ui, Barlow, system-ui, sans-serif); font-variant-numeric: tabular-nums; }
.ds-examples th, .ds-examples td { padding: 10px 14px; border-bottom: 1px solid var(--border, #becddd); }
.ds-examples thead { background: var(--sign, #dbe6f2); }
.ds-examples thead th:not(:first-child), .ds-examples td { text-align: right; }
.ds-examples a { display: inline-block; padding-block: 2px; color: var(--blue, #3a5b8a); text-underline-offset: 4px; }
.ds-examples a:hover { color: var(--navy, #182c4b); }
.ds-examples a:focus-visible { outline: 3px solid var(--focus, #235c9e); outline-offset: 3px; }
@media (max-width: 760px) {
  .ds-examples { font-size: 14px; }
  .ds-examples th, .ds-examples td { padding: 9px 6px; }
}
